import pandas as pd


def apply(df, ctx):
    ctx["unit"] = "first_session_per_user"
    ordered = df.sort_values(["day", "session_id"], kind="mergesort")
    first = ordered.drop_duplicates(subset="user_id", keep="first")
    return first.sort_values("session_id").reset_index(drop=True)
